//! Cargo-driven `libtirpc.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x72fe0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7fefb000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7fefb000000u64)),
        o => panic!("libtirpc-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:oldnames", "import:user32", "import:advapi32", "import:kernel32_vista", "import:ws2_32", "import:msvcrt", "import:kernel32", "import:ntdll", "import:secur32", "body", "engine:delayimp_rust"],
        "x86_64" => &["engine:oldnames", "import:user32", "import:advapi32", "import:kernel32_vista", "import:ws2_32", "import:msvcrt", "import:kernel32", "import:ntdll", "import:secur32", "body", "engine:delayimp_rust"],
        "aarch64" => &["engine:oldnames", "import:user32", "import:advapi32", "import:kernel32_vista", "import:ws2_32", "import:msvcrt", "import:kernel32", "import:ntdll", "import:secur32", "body", "engine:delayimp_rust"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/3rdparty/libtirpc",
        "vendor/libtirpc",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "vendor/libtirpc/tirpc",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "PORTMAP",
        "UNICODE",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_CRT_NONSTDC_NO_DEPRECATE=1",
        "_DLL",
        "_WIN32",
        "_WIN32_WINNT=0x600",
        "__USE_CRTIMP",
    ];

    Linker::new(target_json)
        .c_from_compile_db("libtirpc_shims", &["vendor/libtirpc/src/asprintf.c", "vendor/libtirpc/src/authdes_prot.c", "vendor/libtirpc/src/auth_none.c", "vendor/libtirpc/src/auth_sspi.c", "vendor/libtirpc/src/authsspi_prot.c", "vendor/libtirpc/src/auth_time.c", "vendor/libtirpc/src/auth_unix.c", "vendor/libtirpc/src/authunix_prot.c", "vendor/libtirpc/src/bindresvport.c", "vendor/libtirpc/src/clnt_bcast.c", "vendor/libtirpc/src/clnt_dg.c", "vendor/libtirpc/src/clnt_generic.c", "vendor/libtirpc/src/clnt_perror.c", "vendor/libtirpc/src/clnt_raw.c", "vendor/libtirpc/src/clnt_simple.c", "vendor/libtirpc/src/clnt_vc.c", "vendor/libtirpc/src/des_soft.c", "vendor/libtirpc/src/epoll_sub.c", "vendor/libtirpc/src/getnetconfig.c", "vendor/libtirpc/src/getnetpath.c", "vendor/libtirpc/src/getpeereid.c", "vendor/libtirpc/src/getpublickey.c", "vendor/libtirpc/src/getrpcent.c", "vendor/libtirpc/src/getrpcport.c", "vendor/libtirpc/src/gettimeofday.c", "vendor/libtirpc/src/key_call.c", "vendor/libtirpc/src/key_prot_xdr.c", "vendor/libtirpc/src/mt_misc.c", "vendor/libtirpc/src/netname.c", "vendor/libtirpc/src/netnamer.c", "vendor/libtirpc/src/pmap_clnt.c", "vendor/libtirpc/src/pmap_getmaps.c", "vendor/libtirpc/src/pmap_getport.c", "vendor/libtirpc/src/pmap_prot2.c", "vendor/libtirpc/src/pmap_prot.c", "vendor/libtirpc/src/pmap_rmt.c", "vendor/libtirpc/src/rpcb_clnt.c", "vendor/libtirpc/src/rpcb_prot.c", "vendor/libtirpc/src/rpcb_st_xdr.c", "vendor/libtirpc/src/rpc_callmsg.c", "vendor/libtirpc/src/rpc_commondata.c", "vendor/libtirpc/src/rpcdname.c", "vendor/libtirpc/src/rpc_dtablesize.c", "vendor/libtirpc/src/rpc_generic.c", "vendor/libtirpc/src/rpc_prot.c", "vendor/libtirpc/src/rpc_soc.c", "vendor/libtirpc/src/rtime.c", "vendor/libtirpc/src/svc_auth.c", "vendor/libtirpc/src/svc_auth_none.c", "vendor/libtirpc/src/svc_auth_unix.c", "vendor/libtirpc/src/svc.c", "vendor/libtirpc/src/svc_dg.c", "vendor/libtirpc/src/svc_generic.c", "vendor/libtirpc/src/svc_raw.c", "vendor/libtirpc/src/svc_run.c", "vendor/libtirpc/src/svc_simple.c", "vendor/libtirpc/src/svc_vc.c", "vendor/libtirpc/src/winstubs.c", "vendor/libtirpc/src/wintirpc.c", "vendor/libtirpc/src/xdr_array.c", "vendor/libtirpc/src/xdr.c", "vendor/libtirpc/src/xdr_float.c", "vendor/libtirpc/src/xdr_mem.c", "vendor/libtirpc/src/xdr_rec.c", "vendor/libtirpc/src/xdr_reference.c", "vendor/libtirpc/src/xdr_sizeof.c", "vendor/libtirpc/src/xdr_stdio.c"])
        .whole_c_objects("libtirpc_shims")
        .rc("vendor/libtirpc/libtirpc/libtirpc_ros.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("vendor/libtirpc/libtirpc/libtirpc.spec", "libtirpc.dll")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        .import_lib("dll/win32/ws2_32/ws2_32.spec", "ws2_32.dll", "ws2_32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        .delay_import_lib("dll/win32/secur32/secur32.spec", "secur32.dll", "secur32")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        // No code of its own: link nothing from rustc's bin (its panic
        // handler, i386's rsbegin/rsend), so the PE is cmake's.
        .shell_less()
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
